Azerloot_TT.fr = {
  labels = { upgrades = "Améliorations : ", bonuses = "Vos bonus : ", talents = "Talents : " },
  exact = {
    ["Femme"] = "Female",
    ["Homme"] = "Male",
    ["Langue"] = "Language",
    ["Télécharger le jeu"] = "Download game",
    ["Classe"] = "Class",
    ["POINTS DE VIE"] = "HEALTH",
    ["COMMENCE AVEC"] = "STARTS WITH",
    ["ZONES OUVERTES"] = "ZONES OPEN",
    ["SORTS DISPONIBLES"] = "SPELL POOL",
    ["Sort de départ"] = "Starting spell",
    ["Aléatoire"] = "Random",
    ["Racial, se lance tout seul"] = "Racial, casts on its own",
    ["Équipement"] = "Equipment",
    ["Aucun équipement porté pour l'instant. Les boss en laissent tomber pour votre classe, pour de bon."] = "No gear worn yet. Bosses drop it for your class, for good.",
    ["Armurerie"] = "Armory",
    ["Race, apparence, équipement et tables de butin"] = "Race, look, gear and drop tables",
    ["1 point à dépenser"] = "1 point to spend",
    ["son boss final"] = "its final boss",
    ["le boss final"] = "the final boss",
    ["WASD ou les deux boutons de la souris pour courir · 1 2 3 choisit une carte · R relance · Entrée pour jouer"] = "WASD or both mouse buttons to run · 1 2 3 picks a card · R rerolls · Enter to play",
    ["Options de la partie"] = "Run Options",
    ["Difficulté normale"] = "Normal difficulty",
    ["Nommez votre héros"] = "Name your hero",
    ["Ciblage persistant"] = "Sticky Targeting",
    ["Cocher cette case empêche de désélectionner une cible en cliquant sur le terrain de jeu. Les cibles ne peuvent être effacées qu'en appuyant sur Échap ou en cliquant sur une autre cible."] = "Checking this will prevent the deselection of targets by clicking on the gamefield.  Targets can only be cleared by pressing escape or clicking another target.",
    ["Attaquer en assistant"] = "Attack on assist",
    ["Attaque automatiquement une cible lorsque vous l'obtenez avec \"/assist\"."] = "Automatically attack a target when you acquire it by using \"/assist\".",
    ["Bloquer les échanges"] = "Block Trades",
    ["Bloque toutes les demandes d'échange entrantes."] = "Block all incoming trade requests.",
    ["Auto-ciblage automatique"] = "Auto Self Cast",
    ["Lorsque cette option est activée, les sorts à cible amicale que vous lancez alors que vous avez une cible non amicale ou aucune cible sont automatiquement lancés sur vous-même. Cette fonction peut être associée à un raccourci."] = "When this is enabled, friendly target spells that you cast while you have a non friendly target or no target will automatically be self cast. This function has a hotkey that can be assigned.",
    ["Butin automatique"] = "Auto Loot",
    ["Inverser la souris"] = "Invert Mouse",
    ["Inverse l'effet de la souris sur l'inclinaison de la caméra."] = "Invert the way that the mouse affects camera pitch.",
    ["Sensibilité de la souris"] = "Mouse Sensitivity",
    ["Règle la vitesse de déplacement du curseur."] = "Adjust the speed at which the mouse cursor moves.",
    ["Cliquer pour se déplacer"] = "Click-to-Move",
    ["Utilisez les clics de souris pour déplacer votre personnage vers une destination."] = "Use mouse clicks to move your character to destinations.",
    ["Style de suivi de la caméra"] = "Camera Following Style",
    ["La caméra reste là où vous l'avez placée, sauf lorsque votre personnage se déplace."] = "Set the camera to stay where placed, except when your character is moving.",
    ["Intelligent"] = "Smart",
    ["Toujours"] = "Always",
    ["Jamais"] = "Never",
    ["Suivre le terrain"] = "Follow Terrain",
    ["Change automatiquement l'angle de la caméra selon le terrain. Si votre personnage gravit une pente, la caméra pivote vers le haut ; s'il descend, elle pivote vers le bas."] = "Automatically change the camera angle based on the terrain. If your character climbs a slope, the camera will rotate upwards; if you descend, it will rotate downwards.",
    ["Balancement de la tête"] = "Head Bob",
    ["Simule le balancement de la tête en vue à la première personne."] = "Simulate head bobbing when in first-person perspective.",
    ["Vitesse de suivi auto"] = "Auto-Follow Speed",
    ["Règle la vitesse de la caméra dans les styles de suivi Toujours et Intelligent."] = "Adjust the camera movement speed in Always and Smart following styles.",
    ["Collision avec l'eau"] = "Water Collision",
    ["La caméra reste au-dessus de l'eau quand votre personnage est au-dessus, et dessous quand il est sous l'eau."] = "Set the camera to be above water when your character is above water, and below water when your character is below water.",
    ["Pivot intelligent"] = "Smart Pivot",
    ["Permet de regarder librement quand la caméra touche le sol."] = "Lets you free look when the camera is on the ground.",
    ["Vitesse de vue souris"] = "Mouse Look Speed",
    ["Règle la vitesse à laquelle la caméra tourne en vue souris."] = "Adjust the speed at which you turn the camera when using mouse look.",
    ["Distance max. de la caméra"] = "Max Camera Distance",
    ["Règle la distance maximale à laquelle la caméra vous suit."] = "Adjust the maximum distance the camera will follow behind you.",
    ["Inverser l'axe X de la caméra"] = "Invert Camera X",
    ["Inverse la gauche et la droite du stick droit : le pousser à droite tourne la vue vers la gauche."] = "Flips the right stick's left and right: pushing it right turns the view left.",
    ["Inverser l'axe Y de la caméra"] = "Invert Camera Y",
    ["Inverse le haut et le bas du stick droit sur la vue."] = "Flips the right stick's up and down on the view.",
    ["Vitesse de la caméra"] = "Camera Speed",
    ["La vitesse à laquelle le stick droit tourne et incline la vue."] = "How fast the right stick turns and tilts the view.",
    ["Vitesse du zoom"] = "Zoom Speed",
    ["La vitesse à laquelle les gâchettes et boutons de tranche zooment la vue."] = "How fast the bumpers and triggers zoom the view in and out.",
    ["Zone morte des sticks"] = "Stick Dead Zone",
    ["Jusqu'où un stick doit s'incliner avant de compter. Augmentez-la si le héros ou la vue dérive tout seul."] = "How far a stick tilts before it counts. Raise it if the hero or the view drifts on its own.",
    ["Infobulles améliorées"] = "Enhanced Tooltips",
    ["Affiche des infobulles détaillées dans le coin inférieur droit de l'écran."] = "Enable detailed tooltips in the lower right hand corner of the screen.",
    ["Texte des barres d'état"] = "Status Bar Text",
    ["Affiche toujours le texte sur les barres d'expérience, de vie, de mana, de rage, d'énergie ou de bonheur."] = "Always display the text on XP, health, mana, rage, energy, or happiness status bars.",
    ["Afficher la cible de la cible"] = "Show Target of Target",
    ["Active ou désactive l'affichage de la cible de votre cible."] = "Toggles the display of the target of your target.",
    ["Afficher quand"] = "Show When",
    ["Définit quand afficher la cible de la cible."] = "Sets Target of Target to always display.",
    ["Groupe"] = "Party",
    ["Seul"] = "Solo",
    ["Groupe ou raid"] = "Party or Raid",
    ["Texte de quête instantané"] = "Instant Quest Text",
    ["Cochez cette case pour que le texte des quêtes apparaisse instantanément."] = "Check this to make quest text appear instantly.",
    ["Durée des améliorations"] = "Buff Durations",
    ["Active ou désactive les compteurs de durée des améliorations."] = "Toggle text counters for buff durations on and off.",
    ["Suivi automatique des quêtes"] = "Automatic Quest Tracking",
    ["Les quêtes sont suivies automatiquement pendant 5 minutes lorsque vous remplissez un objectif."] = "Quests are automatically watched for 5 minutes when you achieve a quest objective.",
    ["Filtre de grossièretés"] = "Profanity Filter",
    ["Active le filtrage des grossièretés."] = "Enable profanity filtering.",
    ["Astuces des écrans de chargement"] = "Show Loading Screen Tips",
    ["Décochez cette case pour masquer l'astuce du jour sur les écrans de chargement."] = "Uncheck this to hide the tip of the day in the load screens.",
    ["Infobulles détaillées"] = "Show Detailed Tooltips",
    ["Affiche des informations détaillées sur divers éléments de l'interface. Les joueurs expérimentés voudront peut-être les désactiver."] = "Show detailed information about various user interface elements.  Advanced players may want to turn this off.",
    ["Compteur de dégâts au premier plan"] = "Damage Meter on Top",
    ["Garde le compteur de dégâts au-dessus des cartes de niveau et de bijoux, pour vérifier vos dégâts pendant votre choix."] = "Keeps the damage meter over the level-up and jewelry cards, so you can check your damage while you pick.",
    ["Échelle de l'ATH"] = "HUD Scale",
    ["Règle la taille de l'ATH de la partie : l'horloge et la barre du boss, les victimes et l'or, vos sorts et bijoux, et le compteur de dégâts."] = "Sizes the run's own HUD: the clock and the boss's bar, kills and gold, your spells and jewelry, and the damage meter.",
    ["Afficher l'horloge de la partie"] = "Show Run Clock",
    ["L'horloge de la partie et le temps avant le prochain boss, en haut de l'écran."] = "The run's clock and the time to the next boss, at the top of the screen.",
    ["Afficher les barres de boss"] = "Show Boss Bars",
    ["Les barres de vie des boss et des gardiens éveillés que vous combattez."] = "The health bars of the bosses and awake guardians you are fighting.",
    ["Afficher victimes et or"] = "Show Kills and Gold",
    ["L'encadré de vos victimes et de votre or, près de la minicarte."] = "The box with your kills and gold beside the minimap.",
    ["Afficher le build"] = "Show Build",
    ["Vos sorts et bijoux avec leurs temps de recharge."] = "Your spells and jewelry with their cooldowns.",
    ["Afficher les bannières"] = "Show Banners",
    ["Les messages au centre de l'écran, comme l'arrivée d'un boss."] = "The messages in the middle of the screen, such as a boss arriving.",
    ["Afficher les avis de butin"] = "Show Loot Notices",
    ["L'avis d'une pièce d'équipement lâchée par un boss."] = "The notice of a piece of gear a boss dropped.",
    ["Afficher le compteur de dégâts"] = "Show Damage Meter",
    ["Le bouton du compteur de dégâts sur la minicarte et sa fenêtre."] = "The damage meter's button on the minimap and its window.",
    ["Ouvrir les coffres d'un clic"] = "Open Caches by Clicking",
    ["Les coffres ne s'achètent que lorsque vous faites un clic droit dessus, pas en marchant dessus. Aide à garder une partie sans coffre pour Économe."] = "Caches are bought only when you right-click them, not when you walk over them. Helps keep a run free of caches for Thrifty.",
    ["Garder les niveaux"] = "Store Level-Ups",
    ["Monter de niveau n'interrompt plus le combat. Les niveaux sont gardés, et un bouton « Niveau supérieur ! » au-dessus de vos barres d'action les ouvre quand vous êtes prêt."] = "Level-ups no longer stop the fight. They are stored, and a Level Up! button over your action bars opens them when you are ready.",
    ["Aucun effet de sort"] = "No Spell Effects",
    ["N'affiche aucun effet de sort : ni explosions, ni projectiles, ni lueurs, ni rayons, seulement l'animation d'incantation de votre héros. Les sorts restent audibles. Pour un ordinateur lent."] = "Draws no spell effects: no explosions, missiles, glows or beams, only your hero's casting animation. Spells still sound. For a slow computer.",
    ["Fond du menu principal"] = "Main Menu Background",
    ["Ce qui se trouve derrière le menu principal : la zone choisie, survolée lentement, ou un simple écran noir pour un ordinateur lent ou un téléphone."] = "What the main menu stands over: the picked zone, flown over slowly, or a plain black screen for a slower computer or phone.",
    ["Zone animée"] = "Animated Zone",
    ["Noir"] = "Black",
    ["Statut Discord"] = "Discord Status",
    ["Affiche à quoi vous jouez sur votre profil Discord : le nom, la race et la classe de votre héros, la zone, votre niveau, vos victimes et combats de boss, votre meilleur sort et la durée de la partie. Nécessite l'application Discord ouverte."] = "Shows what you are playing on your Discord profile: your hero's name, race and class, the zone, your level, kills and boss fights, your top spell and the run's time. Needs the Discord app running.",
    ["Toujours afficher les barres d'action"] = "Always Show ActionBars",
    ["Cochez cette option pour toujours afficher les barres d'action supplémentaires."] = "Check this option to always display extra actionbars.",
    ["Verrouiller les barres d'action"] = "Lock ActionBars",
    ["Empêche de prendre ou de déplacer les sorts de la barre d'action. Cette fonction peut être associée à une touche dans l'interface des raccourcis."] = "Prevents the user from picking up/dragging spells on the action bar. This function can be bound to a function key in the keybindings interface.",
    ["Texte de combat flottant"] = "Enable Floating Combat Text",
    ["Cocher cette case affiche des messages de combat supplémentaires sur le terrain de jeu."] = "Checking this will enable additional combat messages to appear in the playfield.",
    ["Mode de défilement du texte"] = "Combat Text Float Mode",
    ["Définit la direction de défilement du texte de combat."] = "Sets the direction that combat text scrolls.",
    ["Vers le haut"] = "Scroll Up",
    ["Vers le bas"] = "Scroll Down",
    ["Afficher vie et mana faibles"] = "Show Low Mana and Health",
    ["Affiche un message quand votre mana ou votre vie passe sous 20 %."] = "Shows a message when you fall below 20% mana or health.",
    ["Afficher les auras"] = "Show Auras",
    ["Affiche un message quand le joueur gagne une aura."] = "Shows a message when the player gains an aura.",
    ["Afficher les auras qui s'estompent"] = "Show Fading Auras",
    ["Affiche un message quand une aura se dissipe sur le joueur."] = "Shows a message when an aura fades from the player.",
    ["Afficher l'état de combat"] = "Show Combat State",
    ["Affiche un message quand vous entrez en combat ou en sortez."] = "Shows a message when you enter or leave combat.",
    ["Afficher esquives/parades/ratés"] = "Show Dodge/Parries/Misses",
    ["Affiche les attaques contre vous qui sont esquivées, parées ou ratées."] = "Shows attacks against you that dodge, parry, or miss.",
    ["Afficher la réduction des dégâts"] = "Show Damage Reduction",
    ["Affiche quand vous résistez aux dégâts d'attaques ou de sorts."] = "Shows when you resist taking damage from attacks or spells.",
    ["Afficher la réputation"] = "Show Reputation",
    ["Affiche un message quand le joueur gagne ou perd de la réputation auprès d'une faction."] = "Shows a message when the player gains or loses reputation with a faction.",
    ["Afficher sorts et techniques réactifs"] = "Show Reactive Spells and Abilities",
    ["Affiche quand des techniques et sorts réactifs propres à votre classe deviennent disponibles (par ex. Fulgurance pour les guerriers)."] = "Shows when reactive class specific abilities and spells become available (e.g. Overpower for warriors).",
    ["Afficher les noms des soigneurs alliés"] = "Show Friendly Healer Names",
    ["Affiche le nom d'un lanceur allié quand il vous lance un sort de soins."] = "Shows the name of a friendly caster when they cast a heal spell on you.",
    ["Afficher les points de combo"] = "Show Combo Points",
    ["Affiche le nombre de vos points de combo à chaque nouveau point obtenu."] = "Shows the number of combo points you have each time you acquire a new one.",
    ["Afficher les gains d'énergie"] = "Show Energy Gains",
    ["Affiche tous les gains instantanés de mana, de rage et d'énergie."] = "Shows all instant gains of mana, rage, and energy.",
    ["Afficher l'honneur gagné"] = "Show Honor Gained",
    ["Affiche l'honneur gagné en tuant d'autres joueurs."] = "Shows the honor you gain from killing other players.",
    ["Afficher les dégâts sur la cible"] = "Show Target Damage",
    ["Affiche les chiffres de dégâts au-dessus des créatures hostiles touchées."] = "Display damage numbers over hostile creatures when damaged.",
    ["Dégâts périodiques"] = "Periodic Damage",
    ["Affiche les dégâts infligés par les effets périodiques comme Pourfendre et Mot de l'ombre : Douleur."] = "Display damage caused by periodic effects such as Rend and Shadow Word: Pain.",
    ["Dégâts du familier"] = "Pet Damage",
    ["Affiche les dégâts infligés par votre familier."] = "Show damage caused by your pet.",
    ["Enregistrer le journal de combat"] = "Save Combat Log",
    ["Écrit chaque ligne du journal de combat dans WoWCombatLog.txt, dans le dossier Logs de benilla-config, à côté du jeu, comme la commande /combatlog. Le fichier grossit tant que cette option est activée."] = "Writes every combat log line to WoWCombatLog.txt in the Logs folder of benilla-config, beside the game, as the /combatlog command does. The file keeps growing while this is on.",
    ["Alerte des membres de guilde"] = "Guild Member Alert",
    ["Affiche un message quand les membres de votre guilde se connectent et se déconnectent."] = "Show a message when your guild members login and logout.",
    ["Supprimer le délai de survol du chat"] = "Remove Chat Hover Delay",
    ["Cochez pour afficher les fenêtres de discussion dès le survol de la souris."] = "Check to show chat windows immediately upon mouseover.",
    ["Bulles de dialogue"] = "Show Chat Bubbles",
    ["Affiche le texte de /dire et /crier dans des bulles au-dessus de la tête des personnages."] = "Shows /say and /yell text in speech bubbles above characters' heads.",
    ["Informations de butin détaillées"] = "Detailed Loot Information",
    ["Décochez pour masquer les messages de jet de butin individuels et n'afficher que le gagnant."] = "Uncheck this to hide individual loot roll messages and only show the winner.",
    ["Bulles de dialogue du groupe"] = "Show Party Chat Bubbles",
    ["Affiche le texte du chat de groupe dans des bulles au-dessus de la tête des membres du groupe."] = "Shows party chat text in speech bubbles above party members' heads.",
    ["Désactiver le filtre anti-spam"] = "Disable Spam Filter",
    ["Désactive le filtrage du spam dans le chat."] = "Disables spam filtering on chat text.",
    ["Barres de nom ennemies"] = "Enemy Name Plates",
    ["Barres de nom amicales"] = "Friendly Name Plates",
    ["Noms des joueurs"] = "Player Names",
    ["Affiche toujours le nom des joueurs dans le monde."] = "Always display player names in the game world.",
    ["Noms de guilde des joueurs"] = "Player Guild Names",
    ["Affiche toujours le nom de guilde des joueurs dans le monde."] = "Always display player guild names in the game world.",
    ["Noms des PNJ"] = "NPC Names",
    ["Affiche toujours le nom des PNJ dans le monde."] = "Always display NPC names in the game world.",
    ["Afficher son propre nom"] = "Show Own Name",
    ["Affiche le nom de votre personnage."] = "Shows your character's name.",
    ["Échelle de l'interface"] = "UI Scale",
    ["Change la taille de l'interface du jeu."] = "Changes the size of the game’s user interface.",
    ["Distance du terrain"] = "Terrain Distance",
    ["Change jusqu'où vous voyez le terrain. Réduisez-la pour améliorer les performances."] = "Changes how far you can see terrain. Decrease to improve performance.",
    ["Détail de l'environnement"] = "Environment Detail",
    ["Détermine jusqu'où vous voyez les objets. Réduisez-le pour améliorer les performances."] = "Controls how far you can see objects. Decrease to improve performance.",
    ["Détail des sorts"] = "Spell Detail",
    ["Détermine le niveau de détail des effets de sorts. Réduisez-le pour améliorer les performances."] = "Controls the detail level of spell effects.  Decrease to improve performance.",
    ["Luminosité"] = "Brightness",
    ["Éclaircit ou assombrit toute l'image : utile surtout la nuit, dans les grottes et en intérieur."] = "Lightens or darkens the whole picture: nights, caves and interiors are what it is for.",
    ["Intensité de la météo"] = "Weather Intensity",
    ["Détermine l'intensité des effets météo. Réduisez-la pour améliorer les performances."] = "Controls the intensity of weather effects.  Decrease to improve performance.",
    ["Mode d'affichage"] = "Display Mode",
    ["Fenêtré (plein écran) remplit l'écran d'une fenêtre sans bordure ; Fenêtré s'exécute dans une fenêtre ordinaire."] = "Windowed (Fullscreen) fills the screen with a borderless window; Windowed runs in an ordinary one.",
    ["Fenêtré (plein écran)"] = "Windowed (Fullscreen)",
    ["Fenêtré"] = "Windowed",
    ["Synchronisation verticale"] = "Vertical Sync",
    ["Synchronise votre fréquence d'images sur une fraction de la fréquence de rafraîchissement de l'écran. Activez-la si vous voyez beaucoup de déchirures d'image."] = "Synchronizes your framerate to some fraction of your monitor's refresh rate. Enable this if you see excessive screen tearing in game.",
    ["Échelle de rendu"] = "Render Scale",
    ["Dessine le monde 3D à une fraction de la résolution de la fenêtre, ou au-delà. Sous 100 %, échange la netteté contre des images par seconde ; au-dessus, lisse les bords au prix des images par seconde."] = "Draws the 3D world at a fraction of the window's resolution, or larger than it. Below 100% trades sharpness for frame rate; above 100% smooths edges at the cost of frame rate.",
    ["Activer tous les sons"] = "Enable All Sound",
    ["Active ou désactive tous les sons du jeu."] = "Enables or disables all game sound.",
    ["Volume général"] = "Master Volume",
    ["Règle le volume sonore général."] = "Adjusts the master sound volume.",
    ["Volume des sons"] = "Sound Volume",
    ["Règle le volume des effets sonores."] = "Adjusts the sound effect volume.",
    ["Volume de la musique"] = "Music Volume",
    ["Règle le volume de la musique de fond."] = "Adjusts the background music volume.",
    ["Volume de l'ambiance"] = "Ambience Volume",
    ["Règle le volume des sons d'ambiance."] = "Adjusts the ambient sound volume.",
    ["Activer la musique"] = "Enable Music",
    ["Active la musique de fond."] = "Enable background music.",
    ["Musique en boucle"] = "Loop Music",
    ["Lance le morceau suivant dès qu'un morceau se termine, au lieu d'attendre un moment de silence."] = "Starts the next music track as soon as one ends, instead of after a stretch of silence.",
    ["Activer l'ambiance"] = "Enable Ambience",
    ["Active les sons d'ambiance."] = "Enable ambient sounds.",
    ["Activer les messages d'erreur parlés"] = "Enable Error Speech",
    ["Active la voix pour les erreurs (par ex. \"Cible hors de portée\")."] = "Enables speech from errors (e.g. \"Target out of range\").",
    ["Son en arrière-plan"] = "Enable Sound in Background",
    ["Garde le son du jeu pendant que vous travaillez dans une autre fenêtre."] = "Keeps the game's sound playing while you are working in another window.",
    ["Titres des joueurs"] = "Player Titles",
    ["Affiche les titres de rang JcJ des joueurs avec leur nom."] = "Shows players' PvP rank titles with their names.",
    ["Multi-échantillonnage"] = "Multisampling",
    ["Adoucit les bords crénelés du monde 3D au prix d'images par seconde ; votre carte graphique peut offrir moins que demandé. Pris en compte au prochain lancement du jeu."] = "Smooths the jagged edges of the 3D world at some cost in frame rate; your graphics card may offer less than asked. Takes effect the next time the game starts.",
    ["Non"] = "Off",
    ["Filtrage anisotrope"] = "Anisotropic Filtering",
    ["Garde le sol et les murs nets vus en biais. Pris en compte au prochain lancement du jeu."] = "Keeps the ground and walls sharp when seen at a slant. Takes effect the next time the game starts.",
    ["Filtrage trilinéaire"] = "Trilinear Filtering",
    ["Adoucit les transitions entre les niveaux de détail d'une texture. Pris en compte au prochain lancement du jeu."] = "Smooths the steps between a texture's levels of detail. Takes effect the next time the game starts.",
    ["Lueur plein écran"] = "Full Screen Glow",
    ["Une douce lueur autour des parties claires de l'image. Désactivez-la pour une image plus nette ou un ordinateur lent."] = "A soft glow around the bright parts of the picture. Turn it off for a sharper picture or a slower computer.",
    ["Effet de mort"] = "Death Effect",
    ["Rend le monde gris tant que votre héros est mort."] = "Turns the world grey while your hero is dead.",
    ["Sons des emotes"] = "Emote Sounds",
    ["Joue les voix des emotes comme /cheer et /laugh."] = "Plays the voices of emotes such as /cheer and /laugh.",
    ["Son au personnage"] = "Sound at Character",
    ["Entend le monde depuis l'endroit où se tient votre héros plutôt que depuis la caméra."] = "Hears the world from where your hero stands rather than from the camera.",
    ["Charger les AddOns périmés"] = "Load out of date AddOns",
    ["Charge aussi les addons conçus pour une autre version du jeu. Ils risquent de ne pas fonctionner."] = "Loads addons made for another version of the game too. They may not work.",
