    ["コボルドの監督官"] = "Kobold Taskmaster",
    ["グラフ・スウィフトバイト"] = "Gruff Swiftbite",
    ["ベリーグラブ"] = "Bellygrub",
    ["ホガー"] = "Hogger",
    ["グルル…新鮮な肉だ！"] = "Grrr... fresh meat!",
    ["マザーファング"] = "Mother Fang",
    ["マザーファングが鉱山から這い出てきた！"] = "Mother Fang skitters out of the mine!",
    ["ラク・ゾール"] = "Rhahk'Zor",
    ["ヴァンクリーフ、お前らの首に大金払う！"] = "VanCleef pay big for your heads!",
    ["ミスター・スマイト"] = "Mr. Smite",
    ["攻撃を受けているぞ！おい野郎ども！侵入者を撃退しろ！"] = "We're under attack! Avast, ye swabs! Repel the invaders!",
    ["エドウィン・ヴァンクリーフ"] = "Edwin VanCleef",
    ["どいつもこいつも飼い犬め！"] = "Lapdogs, all of you!",
    ["ダスクウッド"] = "Duskwood",
    ["ナイトベインの夜"] = "Night of the Nightbane",
    ["レイヴンヒルの墓が口を開けている。木々の間をワーゲンが狩り、モーベント・フェルがダスクウッドの死者を戦へと呼び集める。"] = "The graves of Raven Hill stand open. Worgen hunt between the trees, and Morbent Fel calls the dead of Duskwood to war.",
    ["スケルトンの略奪者"] = "Skeletal Raider",
    ["疫病をまく者"] = "Plague Spreader",
    ["クロゴケグモの幼体"] = "Black Widow Hatchling",
    ["ナイトベインのシャドウウィーバー"] = "Nightbane Shadow Weaver",
    ["腐れた恐怖"] = "Rotting Horror",
    ["ナイトベインのダークランナー"] = "Nightbane Dark Runner",
    ["肉裂き"] = "Fleshripper",
    ["さまよう亡霊"] = "Restless Shade",
    ["骨かじり"] = "Bone Chewer",
    ["ナイトベインのワーゲン・アルファ"] = "Nightbane Worgen Alpha",
    ["腐肉の隠遁蜘蛛"] = "Carrion Recluse",
    ["人喰いのアボミネーション"] = "Flesh Eating Abomination",
    ["ナラクシス"] = "Naraxis",
    ["ナラクシスが枝から降ってきた！"] = "Naraxis drops from the branches!",
    ["モー・ラディム"] = "Mor'Ladim",
    ["死して我が軍に加わるがいい！"] = "You will join my army in death!",
    ["スティッチーズ"] = "Stitches",
    ["スティッチーズ腹へった！スティッチーズ食う！"] = "Stitches hungry! Stitches eat!",
    ["ルポス"] = "Lupos",
    ["ルポスが吠え、ナイトベインが応える！"] = "Lupos howls, and the Nightbane answer!",
    ["モーベント・フェル"] = "Morbent Fel",
    ["レイヴンヒルの死者よ、我が命に従い立ち上がれ！"] = "The dead of Raven Hill rise at my command!",
    ["ウォーソング渓谷"] = "Warsong Gulch",
    ["バーニング・レギオン"] = "The Burning Legion",
    ["渓谷の上に悪魔の門が裂けて開く。インプ、フェルハウンド、サテュロスがなだれ込み、カザック卿がその後に続く。"] = "A demon gate tears open over the gulch. Imps, felhounds and satyrs pour through, and Lord Kazzak follows.",
    ["燃えるインプ"] = "Burning Imp",
    ["フェルハウンド"] = "Felhound",
    ["フェルバット"] = "Fel Bat",
    ["サテュロスのシャドウキャスター"] = "Satyr Shadowcaster",
    ["サテュロスのトリックスター"] = "Satyr Trickster",
    ["ヴォイドウォーカー"] = "Voidwalker",
    ["サキュバス"] = "Succubus",
    ["ファイアインプ"] = "Fire Imp",
    ["マナフィーンド"] = "Mana Fiend",
    ["フェルガードのエリート"] = "Felguard Elite",
    ["インファーナル"] = "Infernal",
    ["ドゥームガード"] = "Doomguard",
    ["ドゥームガードの指揮官"] = "Doomguard Commander",
    ["お前たちの世界は我らが焼き尽くす！"] = "Your world is ours to burn!",
    ["マノロスの伝令"] = "Mannoroth's Herald",
    ["レギオンの前にひざまずけ！"] = "Kneel before the Legion!",
    ["ヴァリマスラス"] = "Varimathras",
    ["ドレッドロードはウォーソングを覚えている。お前はどうだ？"] = "The dreadlords remember Warsong. Do you?",
    ["ヘルヌラス卿"] = "Lord Hel'nurath",
    ["ヘルヌラスを呼び出すのは誰だ？その魂はもらった！"] = "Who dares summon Hel'nurath? Your soul is forfeit!",
    ["カザック卿"] = "Lord Kazzak",
    ["すべての定命の者は滅びる！"] = "All mortals will perish!",
    ["アラシ盆地"] = "Arathi Basin",
    ["高地の蜂起"] = "The Highlands Rise",
    ["盆地の旗が倒れ、高地の者たちがそれを奪いに来る：丘からはボルダーフィストのオーガとウィザーバークのトロール、その背後にはアルタラック最後の領主が送り込んだシンジケートが控える。"] = "With the Basin's banners down, the Highlands come for it: Boulderfist ogres and Witherbark trolls out of the hills, and the Syndicate behind them, sent by the last lord of Alterac to take it for his own.",
    ["フェララス"] = "Feralas",
    ["ダイアモールの門"] = "The Gates of Dire Maul",
    ["ゴードゥンニのオーガがウッドポーのノールとフェララスの野生の獣を引き連れてダイアモールから出撃する。ゴードック王自らが森を奪いに来る。"] = "The Gordunni ogres break out of Dire Maul with the Woodpaw gnolls and the wild things of Feralas behind them. King Gordok himself comes to claim the forest.",
    ["ウッドポーの雑種"] = "Woodpaw Mongrel",
    ["ロングトゥースの走り屋"] = "Longtooth Runner",
    ["スプライトの飛び回り"] = "Sprite Darter",
    ["ウッドポーの神秘家"] = "Woodpaw Mystic",
    ["ゴードゥンニのオーガ"] = "Gordunni Ogre",
    ["ワイルドスポーンのサテュロス"] = "Wildspawn Satyr",
    ["アイアンファーの熊"] = "Ironfur Bear",
    ["ゴードゥンニのオーガメイジ"] = "Gordunni Ogre-Mage",
    ["フェラル・スカーのイエティ"] = "Feral Scar Yeti",
    ["ゴードゥンニの乱暴者"] = "Gordunni Brute",
    ["ワープウッドのトレント"] = "Warpwood Treant",
    ["アイアンバークの守護者"] = "Ironbark Protector",
    ["ゼヴリム・ソーンフーフ"] = "Zevrim Thornhoof",
    ["お前の血が森の腐敗を養うのだ！"] = "Your blood will feed the forest's corruption!",
    ["ワイルドシェイパーのアルジン"] = "Alzzin the Wildshaper",
    ["野生がお前を飲み込むだろう！"] = "The wilds will consume you!",
    ["テンドリス・ワープウッド"] = "Tendris Warpwood",
    ["ワープウッドを乱すのは誰だ？"] = "Who disturbs the Warpwood?",
    ["イモルサー"] = "Immol'thar",
    ["イモルサーが牢獄から解き放たれた！"] = "Immol'thar breaks free of its prison!",
    ["ゴードック王"] = "King Gordok",
    ["オレ潰す！オマエ死ぬ！"] = "Me smash! You die!",
    ["グルバシ闘技場"] = "Gurubashi Arena",
    ["血の神の目覚め"] = "The Blood God Wakes",
    ["ハッカリが闘技場を祭壇に変える。トロール、ラプター、血の神の大蛇がリングを埋め尽くし、魂を剥ぐ者ハッカーが再び世界を歩む。"] = "The Hakkari turn the Arena into an altar. Trolls, raptors and the Blood God's serpents fill the ring, and Hakkar the Soulflayer walks the world again.",
    ["グルバシの斥候"] = "Gurubashi Scout",
    ["ラザシのラプター"] = "Razzashi Raptor",
    ["血を求めるコウモリ"] = "Bloodseeker Bat",
    ["ハッカリのシャドウキャスター"] = "Hakkari Shadowcaster",
    ["グルバシの斧投げ"] = "Gurubashi Axe Thrower",
    ["ズーリアンの虎"] = "Zulian Tiger",
    ["ラザシの大蛇"] = "Razzashi Serpent",
    ["ハッカリの呪術医"] = "Hakkari Witch Doctor",
    ["ハッカーの息子"] = "Son of Hakkar",
    ["グルバシのバーサーカー"] = "Gurubashi Berserker",
    ["ズーリアンのクロコリスク"] = "Zulian Crocolisk",
    ["グルバシのチャンピオン"] = "Gurubashi Champion",
    ["大女司祭ジェクリク"] = "High Priestess Jeklik",
    ["ヒルイーク卿よ、復讐の翼を我に！"] = "Lord Hir'eek, grant me wings of vengeance!",
    ["大司祭ヴェノキシス"] = "High Priest Venoxis",
    ["憎悪のとぐろよ、解き放たれよ！"] = "Let the coils of hate unfurl!",
    ["血の王マンドキル"] = "Bloodlord Mandokir",
    ["貴様らの魂をハッカー様に捧げてやる！"] = "I'll feed your souls to Hakkar himself!",
    ["呪術師ジンドー"] = "Jin'do the Hexxer",
    ["大ショーへようこそ、友よ。さあさあ、死にに来な！"] = "Welcome to da great show, friends. Step right up to die!",
    ["魂を剥ぐ者ハッカー"] = "Hakkar the Soulflayer",
    ["驕りは汝らの世界の終焉を告げる。来たれ、定命の者よ！魂を剥ぐ者の怒りを受けよ！"] = "PRIDE HERALDS THE END OF YOUR WORLD. COME, MORTALS! FACE THE WRATH OF THE SOULFLAYER!",
    ["アルタラック・ヴァレー"] = "Alterac Valley",
    ["凍てつく荒野"] = "The Frozen Wilds",
    ["谷が目を覚ます。鉱山からトログが群がり出て、狼たちは飢え、氷の王が雪の下で動き出す。"] = "The valley wakes. Troggs swarm from the mines, the wolves are starving, and the Ice Lord stirs beneath the snow.",
    ["トログの穴掘り"] = "Trogg Tunneler",
    ["飢えたフロストウルフ"] = "Starving Frostwolf",
    ["ウィンターアックスの斧投げ"] = "Winterax Axe Thrower",
    ["クラッシュリッジのオーガメイジ"] = "Crushridge Ogre Mage",
    ["スノーフォールのウェンディゴ"] = "Snowfall Wendigo",
    ["クラッシュリッジの乱暴者"] = "Crushridge Brute",
    ["氷のレヴナント"] = "Ice Revenant",
    ["ウィンターアックスのシャドウハンター"] = "Winterax Shadow Hunter",
    ["フロストウルフの群れの長"] = "Frostwolf Packleader",
    ["アルタラックのイエティの王"] = "Alterac Yeti Lord",
    ["山の巨人"] = "Mountain Giant",
    ["ウィンターアックスの将軍"] = "Winterax Warlord",
    ["ブラッドレイジャーのコラク"] = "Korrak the Bloodrager",
    ["コラク、弱いやつ潰す！"] = "Korrak smash puny ones!",
    ["森の王アイヴァス"] = "Ivus the Forest Lord",
    ["森の眠りを乱すのは誰だ？"] = "Who disturbs the slumber of the forest?",
    ["氷の王ロクホラー"] = "Lokholar the Ice Lord",
    ["我は氷の王。貴様らの血は血管の中で凍りつくのだ！"] = "I am the Ice Lord. Your blood will freeze in your veins!",
    ["凍れる巨神グレイシャス"] = "Glacius the Frozen Titan",
    ["山は覚えている。山がお前を埋めるだろう！"] = "The mountain remembers. The mountain will bury you!",
    ["アズレゴス"] = "Azuregos",
    ["この地は我が庇護の下にある。秘術の神秘が侵されることはない！"] = "This place is under my protection. The mysteries of the arcane shall remain inviolate!",
    ["ブラックロック山"] = "Blackrock Mountain",
    ["ブラックロックの王"] = "The Lord of Blackrock",
    ["ダークアイアンとブラックロック氏族が火のエレメンタルとドラゴン族を伴い、共に山から進軍する。その上空をブラックロックの王が旋回する。"] = "The Dark Iron and the Blackrock clan march out of the mountain together, fire elementals and dragonkin at their side. Above them circles the Lord of Blackrock.",
    ["ダークアイアンの奴隷商人"] = "Dark Iron Slaver",
    ["黒竜の幼体"] = "Black Broodling",
    ["ブラックロックの兵卒"] = "Blackrock Grunt",
    ["ダークアイアンのジオマンサー"] = "Dark Iron Geomancer",
    ["アンヴィルレイジの衛兵"] = "Anvilrage Guardsman",
    ["燃え盛るエレメンタル"] = "Blazing Elemental",
    ["ファイアガットのオーガ"] = "Firegut Ogre",
    ["黒竜族"] = "Black Wyrmkin",
    ["ファイアガードの破壊者"] = "Fireguard Destroyer",
    ["コアハウンド"] = "Core Hound",
    ["ブラックドレイク"] = "Black Drake",
    ["溶岩の巨人"] = "Molten Giant",
    ["アンガーフォージ将軍"] = "General Angerforge",
    ["ダークアイアンよ！武器を取れ！侵入者を叩き潰せ！"] = "Dark Iron! To arms! Crush the intruders!",
    ["大族長レンド・ブラックハンド"] = "Warchief Rend Blackhand",
    ["ブラックロックは決して落ちぬ！真のホードのために！"] = "Blackrock will never fall! For the true Horde!",
    ["皇帝ダグラン・サウリッサン"] = "Emperor Dagran Thaurissan",
    ["玉座を守りに来い！"] = "Come to aid the Throne!",
    ["執事長エグゼキュータス"] = "Majordomo Executus",
    ["無謀な定命の者どもめ！生ける炎の息子たちに挑める者などいない！"] = "Reckless mortals! None may challenge the sons of the living flame!",
    ["ネファリアン"] = "Nefarian",
    ["よくやった、我が下僕たちよ。定命の者の勇気が衰え始めた！さあ、ブラックロック・スパイアの真の王を相手にどう戦うか見せてもらおう！"] = "Well done, my minions. The mortals' courage begins to wane! Now let's see how they contend with the true Lord of Blackrock Spire!",
    ["アン・キラージの門"] = "Gates of Ahn'Qiraj",
    ["古き神の胎動"] = "The Old God Stirs",
    ["スカラベの壁が崩れた。シリシッドの群れとキラージの軍団が砂の上に溢れ出し、その背後でクトゥーンが目を開く。"] = "The Scarab Wall has fallen. The silithid swarm and the Qiraji legions spill across the sands, and behind them C'Thun opens its eye.",
    ["シリシッドの群がり"] = "Silithid Swarmer",
    ["シリシッドの這い寄り"] = "Silithid Creeper",
    ["ハイヴ・ザーラの刺し手"] = "Hive'Zara Stinger",
    ["トワイライトのジオロード"] = "Twilight Geolord",
    ["キラージの剣闘士"] = "Qiraji Gladiator",
    ["ストーンラッシュのスコーピッド"] = "Stonelash Scorpid",
    ["シリシッドの略奪者"] = "Silithid Ravager",
