    ["Otevírat truhly kliknutím"] = "Open Caches by Clicking",
    ["Truhly kupuješ jen kliknutím pravým tlačítkem, ne tím, že na ně vstoupíš. Pomůže projít výpravu bez truhel pro úspěch Šetrný."] = "Caches are bought only when you right-click them, not when you walk over them. Helps keep a run free of caches for Thrifty.",
    ["Uchovávat úrovně"] = "Store Level-Ups",
    ["Nová úroveň už nepřeruší boj. Úrovně se uchovají a tlačítko Nová úroveň! nad lištami akcí je otevře, až budeš připraven."] = "Level-ups no longer stop the fight. They are stored, and a Level Up! button over your action bars opens them when you are ready.",
    ["Bez efektů kouzel"] = "No Spell Effects",
    ["Nevykresluje efekty kouzel: žádné exploze, střely, záře ani paprsky, jen animaci sesílání tvého hrdiny. Zvuky kouzel zůstanou. Pro slabší počítač."] = "Draws no spell effects: no explosions, missiles, glows or beams, only your hero's casting animation. Spells still sound. For a slow computer.",
    ["Pozadí hlavního menu"] = "Main Menu Background",
    ["Co je vidět za hlavním menu: vybraná oblast, pomalu sledovaná z letu, nebo prostá černá obrazovka pro slabší počítač či telefon."] = "What the main menu stands over: the picked zone, flown over slowly, or a plain black screen for a slower computer or phone.",
    ["Animovaná oblast"] = "Animated Zone",
    ["Černé"] = "Black",
    ["Stav na Discordu"] = "Discord Status",
    ["Ukazuje na tvém profilu Discord, co hraješ: jméno, rasu a povolání hrdiny, oblast, úroveň, zabití a souboje s bossy, nejlepší kouzlo a čas výpravy. Vyžaduje spuštěnou aplikaci Discord."] = "Shows what you are playing on your Discord profile: your hero's name, race and class, the zone, your level, kills and boss fights, your top spell and the run's time. Needs the Discord app running.",
    ["Vždy zobrazit lišty akcí"] = "Always Show ActionBars",
    ["Zaškrtni, aby se vždy zobrazovaly další lišty akcí."] = "Check this option to always display extra actionbars.",
    ["Zamknout lišty akcí"] = "Lock ActionBars",
    ["Zabrání zvedání a přetahování kouzel z lišty akcí. Funkci lze přiřadit klávese v nastavení kláves."] = "Prevents the user from picking up/dragging spells on the action bar. This function can be bound to a function key in the keybindings interface.",
    ["Plovoucí text boje"] = "Enable Floating Combat Text",
    ["Je-li zaškrtnuto, v herním poli se objevují další zprávy o boji."] = "Checking this will enable additional combat messages to appear in the playfield.",
    ["Směr textu boje"] = "Combat Text Float Mode",
    ["Nastaví směr posouvání textu boje."] = "Sets the direction that combat text scrolls.",
    ["Nahoru"] = "Scroll Up",
    ["Dolů"] = "Scroll Down",
    ["Oblouk"] = "Arc",
    ["Nízká mana a zdraví"] = "Show Low Mana and Health",
    ["Zobrazí zprávu, když mana nebo zdraví klesnou pod 20 %."] = "Shows a message when you fall below 20% mana or health.",
    ["Zobrazit aury"] = "Show Auras",
    ["Zobrazí zprávu, když hráč získá auru."] = "Shows a message when the player gains an aura.",
    ["Zobrazit mizící aury"] = "Show Fading Auras",
    ["Zobrazí zprávu, když aura z hráče zmizí."] = "Shows a message when an aura fades from the player.",
    ["Zobrazit stav boje"] = "Show Combat State",
    ["Zobrazí zprávu při vstupu do boje a při jeho opuštění."] = "Shows a message when you enter or leave combat.",
    ["Zobrazit úhyby/odrazy/minutí"] = "Show Dodge/Parries/Misses",
    ["Zobrazí útoky proti tobě, kterým ses vyhnul, které jsi odrazil nebo které minuly."] = "Shows attacks against you that dodge, parry, or miss.",
    ["Zobrazit snížení poškození"] = "Show Damage Reduction",
    ["Zobrazí, když odoláš poškození od útoků nebo kouzel."] = "Shows when you resist taking damage from attacks or spells.",
    ["Zobrazit reputaci"] = "Show Reputation",
    ["Zobrazí zprávu, když hráč získá nebo ztratí reputaci u frakce."] = "Shows a message when the player gains or loses reputation with a faction.",
    ["Zobrazit reaktivní schopnosti"] = "Show Reactive Spells and Abilities",
    ["Zobrazí, kdy se reaktivní schopnosti a kouzla povolání stanou dostupnými (např. Přemožení u válečníků)."] = "Shows when reactive class specific abilities and spells become available (e.g. Overpower for warriors).",
    ["Jména přátelských léčitelů"] = "Show Friendly Healer Names",
    ["Zobrazí jméno přátelské postavy, když na tebe sesílá léčení."] = "Shows the name of a friendly caster when they cast a heal spell on you.",
    ["Zobrazit kombo body"] = "Show Combo Points",
    ["Zobrazí počet kombo bodů pokaždé, když získáš nový."] = "Shows the number of combo points you have each time you acquire a new one.",
    ["Zobrazit přírůstky energie"] = "Show Energy Gains",
    ["Zobrazí všechny okamžité přírůstky many, vzteku a energie."] = "Shows all instant gains of mana, rage, and energy.",
    ["Zobrazit získanou čest"] = "Show Honor Gained",
    ["Zobrazí čest získanou za zabíjení jiných hráčů."] = "Shows the honor you gain from killing other players.",
    ["Poškození cíle"] = "Show Target Damage",
    ["Zobrazuj čísla poškození nad zraněnými nepřáteli."] = "Display damage numbers over hostile creatures when damaged.",
    ["Periodické poškození"] = "Periodic Damage",
    ["Zobrazuj poškození od periodických efektů, jako je Rozervání a Slovo stínu: Bolest."] = "Display damage caused by periodic effects such as Rend and Shadow Word: Pain.",
    ["Poškození spojence"] = "Pet Damage",
    ["Zobrazuj poškození, které způsobuje tvůj mazlíček."] = "Show damage caused by your pet.",
    ["Ukládat záznam boje"] = "Save Combat Log",
    ["Zapisuje každý řádek záznamu boje do souboru WoWCombatLog.txt ve složce Logs v benilla-config vedle hry, jako to dělá příkaz /combatlog. Dokud je volba zapnutá, soubor stále roste."] = "Writes every combat log line to WoWCombatLog.txt in the Logs folder of benilla-config, beside the game, as the /combatlog command does. The file keeps growing while this is on.",
    ["Oznámení cechu"] = "Guild Member Alert",
    ["Zobrazuj zprávu, když se členové cechu přihlásí a odhlásí."] = "Show a message when your guild members login and logout.",
    ["Bez zpoždění chatu"] = "Remove Chat Hover Delay",
    ["Zaškrtni, aby se okna chatu objevila hned po najetí myší."] = "Check to show chat windows immediately upon mouseover.",
    ["Bubliny chatu"] = "Show Chat Bubbles",
    ["Zobrazuje text /say a /yell v bublinách nad hlavami postav."] = "Shows /say and /yell text in speech bubbles above characters' heads.",
    ["Podrobné informace o kořisti"] = "Detailed Loot Information",
    ["Odškrtni pro skrytí jednotlivých zpráv o losování kořisti a zobrazení jen vítěze."] = "Uncheck this to hide individual loot roll messages and only show the winner.",
    ["Bubliny chatu skupiny"] = "Show Party Chat Bubbles",
    ["Zobrazuje text chatu skupiny v bublinách nad hlavami jejích členů."] = "Shows party chat text in speech bubbles above party members' heads.",
    ["Vypnout filtr spamu"] = "Disable Spam Filter",
    ["Vypne filtrování spamu v chatu."] = "Disables spam filtering on chat text.",
    ["Jmenovky nepřátel"] = "Enemy Name Plates",
    ["Jmenovky spojenců"] = "Friendly Name Plates",
    ["Jména hráčů"] = "Player Names",
    ["Vždy zobrazuj jména hráčů v herním světě."] = "Always display player names in the game world.",
    ["Cechy hráčů"] = "Player Guild Names",
    ["Vždy zobrazuj názvy cechů hráčů v herním světě."] = "Always display player guild names in the game world.",
    ["Jména NPC"] = "NPC Names",
    ["Vždy zobrazuj jména nehráčských postav v herním světě."] = "Always display NPC names in the game world.",
    ["Zobrazit vlastní jméno"] = "Show Own Name",
    ["Zobrazí jméno tvé postavy."] = "Shows your character's name.",
    ["Velikost rozhraní"] = "UI Scale",
    ["Mění velikost herního rozhraní."] = "Changes the size of the game’s user interface.",
    ["Dohled terénu"] = "Terrain Distance",
    ["Mění, jak daleko je vidět terén. Sniž pro lepší výkon."] = "Changes how far you can see terrain. Decrease to improve performance.",
    ["Detaily okolí"] = "Environment Detail",
    ["Určuje, jak daleko jsou vidět objekty. Sniž pro lepší výkon."] = "Controls how far you can see objects. Decrease to improve performance.",
    ["Detaily kouzel"] = "Spell Detail",
    ["Určuje úroveň detailů efektů kouzel. Sniž pro lepší výkon."] = "Controls the detail level of spell effects.  Decrease to improve performance.",
    ["Jas"] = "Brightness",
    ["Zesvětlí nebo ztmaví celý obraz: hodí se v noci, v jeskyních a uvnitř budov."] = "Lightens or darkens the whole picture: nights, caves and interiors are what it is for.",
    ["Intenzita počasí"] = "Weather Intensity",
    ["Určuje intenzitu efektů počasí. Sniž pro lepší výkon."] = "Controls the intensity of weather effects.  Decrease to improve performance.",
    ["Režim zobrazení"] = "Display Mode",
    ["Okno (celá obrazovka) vyplní obrazovku oknem bez rámečku; Okno běží v obyčejném okně."] = "Windowed (Fullscreen) fills the screen with a borderless window; Windowed runs in an ordinary one.",
    ["Okno (celá obrazovka)"] = "Windowed (Fullscreen)",
    ["Okno"] = "Windowed",
    ["Vertikální synchronizace"] = "Vertical Sync",
    ["Synchronizuje počet snímků s obnovovací frekvencí monitoru. Zapni, pokud vidíš trhání obrazu."] = "Synchronizes your framerate to some fraction of your monitor's refresh rate. Enable this if you see excessive screen tearing in game.",
    ["Měřítko vykreslování"] = "Render Scale",
    ["Vykresluje 3D svět ve zlomku rozlišení okna nebo ve větším. Pod 100 % vyměňuje ostrost za plynulost; nad 100 % vyhlazuje hrany na úkor plynulosti."] = "Draws the 3D world at a fraction of the window's resolution, or larger than it. Below 100% trades sharpness for frame rate; above 100% smooths edges at the cost of frame rate.",
    ["Zapnout zvuk"] = "Enable All Sound",
    ["Zapne nebo vypne všechny zvuky hry."] = "Enables or disables all game sound.",
    ["Hlavní hlasitost"] = "Master Volume",
    ["Nastaví hlavní hlasitost zvuku."] = "Adjusts the master sound volume.",
    ["Hlasitost efektů"] = "Sound Volume",
    ["Nastaví hlasitost zvukových efektů."] = "Adjusts the sound effect volume.",
    ["Hlasitost hudby"] = "Music Volume",
    ["Nastaví hlasitost hudby v pozadí."] = "Adjusts the background music volume.",
    ["Hlasitost okolí"] = "Ambience Volume",
    ["Nastaví hlasitost zvuků okolí."] = "Adjusts the ambient sound volume.",
    ["Zapnout hudbu"] = "Enable Music",
    ["Zapne hudbu v pozadí."] = "Enable background music.",
    ["Hudba bez přestávek"] = "Loop Music",
    ["Další skladba začne hned po skončení předchozí, bez chvíle ticha."] = "Starts the next music track as soon as one ends, instead of after a stretch of silence.",
    ["Zapnout zvuky okolí"] = "Enable Ambience",
    ["Zapne zvuky okolí."] = "Enable ambient sounds.",
    ["Hlasová chybová hlášení"] = "Enable Error Speech",
    ["Zapne hlasová chybová hlášení (např. \"Cíl je mimo dosah\")."] = "Enables speech from errors (e.g. \"Target out of range\").",
    ["Zvuk na pozadí"] = "Enable Sound in Background",
    ["Zvuk hry hraje dál, i když pracuješ v jiném okně."] = "Keeps the game's sound playing while you are working in another window.",
    ["Tituly hráčů"] = "Player Titles",
    ["Zobrazuje u jmen hráčů jejich PvP tituly."] = "Shows players' PvP rank titles with their names.",
    ["Vyhlazuje zubaté hrany 3D světa za cenu snímkové frekvence; grafická karta může nabídnout méně, než je zvoleno. Projeví se při příštím spuštění hry."] = "Smooths the jagged edges of the 3D world at some cost in frame rate; your graphics card may offer less than asked. Takes effect the next time the game starts.",
    ["Vypnuto"] = "Off",
    ["Anizotropní filtrování"] = "Anisotropic Filtering",
    ["Udržuje zem a stěny ostré i při pohledu pod úhlem. Projeví se při příštím spuštění hry."] = "Keeps the ground and walls sharp when seen at a slant. Takes effect the next time the game starts.",
    ["Trilineární filtrování"] = "Trilinear Filtering",
    ["Vyhlazuje přechody mezi úrovněmi detailu textur. Projeví se při příštím spuštění hry."] = "Smooths the steps between a texture's levels of detail. Takes effect the next time the game starts.",
    ["Celoobrazovkové záření"] = "Full Screen Glow",
    ["Jemná zář kolem světlých částí obrazu. Vypněte pro ostřejší obraz nebo na pomalém počítači."] = "A soft glow around the bright parts of the picture. Turn it off for a sharper picture or a slower computer.",
    ["Efekt smrti"] = "Death Effect",
    ["Zbarví svět do šeda, dokud je váš hrdina mrtvý."] = "Turns the world grey while your hero is dead.",
    ["Zvuky emotů"] = "Emote Sounds",
    ["Přehrává hlasy emotů, jako jsou /cheer a /laugh."] = "Plays the voices of emotes such as /cheer and /laugh.",
    ["Zvuk u postavy"] = "Sound at Character",
    ["Svět je slyšet z místa, kde stojí hrdina, ne z kamery."] = "Hears the world from where your hero stands rather than from the camera.",
    ["Načítat zastaralé doplňky"] = "Load out of date AddOns",
    ["Načte i doplňky vytvořené pro jinou verzi hry. Nemusí fungovat."] = "Loads addons made for another version of the game too. They may not work.",
    ["Nízké"] = "Low",
    ["Střední"] = "Medium",
    ["Vysoké"] = "High",
    ["Minimální"] = "Minimal",
    ["Plné"] = "Full",
    ["Ovládání"] = "Controls",
    ["Ovladač"] = "Gamepad",
    ["Rozhraní"] = "Interface",
    ["Lišty akcí"] = "Action Bars",
