    ["Doplňky"] = "AddOns",
    ["Uložené hry"] = "Saves",
    ["Výchozí"] = "Defaults",
    ["Hotovo"] = "Done",
    ["Klikni na klávesu a pak stiskni klávesu, tlačítko myši nebo kolečko pro přiřazení. Pravým kliknutím přiřazení odstraníš."] = "Click a key, then press the key, mouse button or wheel to bind to it. Right-click a key to unbind it.",
    ["Doplňky se zapínají a vypínají pro všechny hrdiny; načtou se při příští výpravě."] = "AddOns are turned on or off for every hero and load at your next run.",
    ["Import uložené hry nahradí celý tvůj postup tím ze souboru."] = "Importing a save replaces all of your progress with the one in the file.",
    ["Levá páčka pohybuje, pravá otáčí pohled, A skáče, tlačítka a spouště přibližují, Y otevře uchované úrovně. Změny platí hned."] = "Left stick moves, right stick turns the view, A jumps, bumpers and triggers zoom, Y opens stored level-ups. Changes apply at once.",
    ["Změny se ukládají hned a platí od příští výpravy."] = "Changes are saved at once and apply to your next run.",
    ["Instaluji..."] = "Installing...",
    ["Nainstalovat doplňky"] = "Install AddOns",
    ["Vyber jeden nebo více souborů .zip s doplňky. Fungují doplňky pro WoW 1.12."] = "Pick one or more addon .zip files. AddOns made for WoW 1.12 work.",
    ["Otevřít složku doplňků"] = "Open AddOns Folder",
    ["Nejsou nainstalovány žádné doplňky."] = "No addons are installed.",
    ["Zastaralý"] = "Out of date",
    ["Načítán podle potřeby"] = "Loads when needed",
    ["Odstranit"] = "Remove",
    ["Tvůj postup (hrdinové, oblasti otevřené každým povoláním, výbava, talenty a kodex) jako soubor: pro uchování kopie nebo přenesení na jiný počítač či prohlížeč."] = "Your progress (heroes, the zones each class has opened, gear, talents and the codex) as a file: to keep a copy, or to carry it to another computer or browser.",
    ["Exportovat uloženou hru"] = "Export Save",
    ["Importovat uloženou hru"] = "Import Save",
    ["Otevřít složku uložených her"] = "Open Saves Folder",
    ["Nahradit"] = "Replace",
    ["Zrušit"] = "Cancel",
    ["Soubory uložených her"] = "Save files",
    ["Zatím žádné soubory uložených her."] = "No save files yet.",
    ["Zálohy"] = "Backups",
    ["Za každou hodinu hraní si hra uloží zálohu tvého postupu (posledních 5). Importuj ji, chceš-li se k ní vrátit."] = "Every hour you play, the game keeps a backup of your progress (the last 5). Import one to go back to it.",
    ["Zatím žádné zálohy."] = "No backups yet.",
    ["Obnovit"] = "Restore",
    ["Importovat"] = "Import",
    ["Uložená hra byla stažena."] = "Your save was downloaded.",
    ["Chybí složka pro export."] = "There is no folder to export to.",
    ["Přiřazení kláves se z herních dat nepodařilo načíst."] = "The key bindings could not be read from the game's data.",
    ["Stiskni klávesu"] = "Press a key",
    ["Nepřiřazeno"] = "Not Bound",
    ["Toto není soubor uložené hry Azeroth Survivors."] = "That is not an Azeroth Survivors save file.",
    ["Tento soubor uložené hry je poškozený nebo byl změněn a nedá se přečíst."] = "That save file is damaged or was edited, and cannot be read.",
    ["nekonečno"] = "endless",
