    ["Karakter"] = "Character",
    ["Koleksiyon"] = "Collection",
    ["Ganimet Tabloları"] = "Drop Tables",
    ["Kodeks"] = "Codex",
    ["Başarımlar"] = "Achievements",
    ["Ödüller"] = "Rewards",
    ["Görünüm"] = "Appearance",
    ["Giydiğin hiçbir şey henüz bir şey katmıyor: sınıfın ekipmanını boss'lar düşürür."] = "Nothing worn adds anything yet: bosses drop the class's gear.",
    ["Boş"] = "Empty",
    ["GİZLİ"] = "HIDDEN",
    ["GÖRÜNÜM"] = "LOOK",
    ["G"] = "E",
    ["Gö"] = "L",
    ["Koleksiyon Kaydı"] = "Collection Log",
    ["BÖLGELERİNDE BULUNACAK · HİÇBİR ŞEY: SONRAKİ BÖLGEYİ AÇ"] = "STILL TO FIND IN YOUR ZONES · NOTHING: OPEN THE NEXT ZONE",
    ["kilitli"] = "locked",
    ["Toplandı"] = "Collected",
    ["Henüz değil"] = "Not yet",
    ["Ayrıntılar"] = "Details",
    ["Ne kattığını ve hangi boss'ların düşürdüğünü görmek için koleksiyondan ya da ganimet tablolarından bir parça seç; görünümünü seçmek için soldan bir yuva seç."] = "Pick a piece in the collection or the drop tables to see what it adds and which bosses drop it, or a slot on the left to choose its look.",
    ["Koleksiyonunda"] = "In your collection",
    ["Henüz toplanmadı"] = "Not yet collected",
    ["DÜŞÜREN"] = "DROPS FROM",
    ["Çıkar"] = "Unequip",
    ["Giy"] = "Equip",
    ["Kahramanın bu yuvada gösterdiği. Yalnızca giyilen parçalar bonuslarını verir."] = "What the hero shows in this slot. Only worn pieces add their bonuses.",
    ["Giyilen parça"] = "Worn piece",
    ["Bu parça"] = "This piece",
    ["Başlangıç kıyafetleri"] = "Starting clothes",
    ["Gizli"] = "Hidden",
    ["Gösterilen"] = "Showing",
    ["Çevirmek için kahramanı sürükle"] = "Drag the hero to turn",
    ["Özellikler"] = "Features",
    ["Kahramanın orada ne göstereceğini seçmek için soldan bir yuva seç."] = "Pick a slot on the left to choose what the hero shows there.",
    ["Sıradan"] = "Common",
    ["Nadir Olmayan"] = "Uncommon",
    ["Nadir"] = "Rare",
    ["Destansı"] = "Epic",
    ["Efsanevi"] = "Legendary",
    ["Büyülerin 1 hedefi daha vurur."] = "Your spells strike 1 more target.",
    ["Savaşçı"] = "Warrior",
    ["Kargaşanın ortasında durdurulamaz. Devasa can, yarıp geçen vuruşlar ve her öldürme öfkeyi besler."] = "Unstoppable in the thick of it. Huge health, cleaving swings, and every kill feeds the fury.",
    ["Kutsal toprak ve adil çekiçler. Kendini iyileştirir, arada bir ölümü savuşturur."] = "Holy ground and righteous hammers. Heals himself, shrugs off death once in a while.",
    ["Avcı"] = "Hunter",
    ["Uzaktan gelen ölüm. Mesafeni korudukça oklar, tuzaklar ve ok yağmurları."] = "Death from range. Arrows, traps and volleys, as long as you keep your distance.",
    ["Haydut"] = "Rogue",
    ["Hızlı, kırılgan ve ölümcül. En hızlı kahraman, elitleri silen kritiklerle."] = "Fast, fragile and lethal. The quickest hero, with crits that delete elites.",
    ["Rahip"] = "Priest",
    ["Işık ve Gölge. Kalkanlar ve iyileştirmeler seni hayatta tutarken acı sürüye yayılır."] = "Light and Shadow. Shields and heals keep you alive while pain spreads through the horde.",
    ["Şaman"] = "Shaman",
    ["Düşmandan düşmana sıçrayan fırtınalar ve yanında savaşan totemler."] = "Storms that jump from foe to foe, and totems that fight beside you.",
    ["Büyücü"] = "Mage",
    ["Cam top. Azeroth'un en büyük alan hasarı ve arkasına saklanacak hiçbir şey."] = "The glass cannon. The biggest area damage in Azeroth, and nothing to hide behind.",
    ["Kara Büyücü"] = "Warlock",
    ["Lanetler ve ateş. Zamanla verilen hasar seni kovalayan her şeyin üzerinde birikir."] = "Curses and fire. Damage over time stacks up on everything that chases you.",
    ["Ay, fırtına ve büyüme. Kökler, kasırgalar ve en istikrarlı kendini iyileştirme."] = "Moon, storm and growth. Roots, hurricanes and the steadiest self-healing.",
    ["İnsan"] = "Human",
    ["Perception: her 30 sn'de 10 sn boyunca +%15 hasar"] = "Perception: every 30 sec, +15% damage for 10 sec",
    ["The Human Spirit: +%10 deneyim"] = "The Human Spirit: +10% experience",
    ["Diplomacy: +%20 altın"] = "Diplomacy: +20% gold",
    ["Ork"] = "Orc",
    ["Blood Fury: her 40 sn'de 12 sn boyunca +%35 hasar"] = "Blood Fury: every 40 sec, +35% damage for 12 sec",
    ["Hardiness: +%10 azami can"] = "Hardiness: +10% max health",
    ["Cüce"] = "Dwarf",
    ["Stoneform: her 45 sn'de azami canın %30'unu emen bir kalkan"] = "Stoneform: every 45 sec, a shield absorbing 30% of max health",
    ["Gun Specialization: +%6 hasar"] = "Gun Specialization: +6% damage",
    ["Treasure Finding: +%30 toplama menzili"] = "Treasure Finding: +30% pickup range",
    ["Gece Elfi"] = "Night Elf",
    ["Shadowmeld: ölüme yakınken 3 sn bağışıklık (75 sn bekleme süresi)"] = "Shadowmeld: near death, 3 sec of immunity (75 sec cooldown)",
    ["Quickness: +%8 hareket hızı"] = "Quickness: +8% movement speed",
    ["Nature Resistance: +%5 hasar azaltma"] = "Nature Resistance: +5% damage reduction",
    ["Ölümsüz"] = "Undead",
    ["Will of the Forsaken: ölüme yakınken 4 sn bağışıklık (60 sn bekleme süresi)"] = "Will of the Forsaken: near death, 4 sec of immunity (60 sec cooldown)",
    ["Cannibalize: her öldürme 1 can iyileştirir"] = "Cannibalize: every kill heals 1 health",
    ["Shadow Resistance: +%4 hasar azaltma"] = "Shadow Resistance: +4% damage reduction",
    ["War Stomp: her 15 sn'de yakındaki düşmanları 2 sn sersemletir"] = "War Stomp: every 15 sec, stuns nearby enemies for 2 sec",
    ["Endurance: +%15 azami can"] = "Endurance: +15% max health",
    ["Gnom"] = "Gnome",
    ["Escape Artist: her 20 sn'de yakındaki düşmanları 2 sn yerinde sabitler"] = "Escape Artist: every 20 sec, roots nearby enemies for 2 sec",
    ["Expansive Mind: -%8 bekleme süresi"] = "Expansive Mind: -8% cooldowns",
    ["Engineering Specialization: +%20 şans"] = "Engineering Specialization: +20% luck",
    ["Trol"] = "Troll",
    ["Berserking: her 35 sn'de 10 sn boyunca bekleme süreleri %30 daha hızlı dolar"] = "Berserking: every 35 sec, cooldowns recover 30% faster for 10 sec",
    ["Regeneration: saniyede +1.5 can"] = "Regeneration: +1.5 health per second",
    ["Throwing Specialization: +%3 kritik vuruş"] = "Throwing Specialization: +3% critical strike",
    ["Defias Ayaklanması"] = "The Defias Uprising",
    ["Kobold'lar Jasperlode Madeni'nden akın ediyor, gnoll'lar nehri geçiyor ve Defias Kardeşliği çiftliklere yürüyor. Liderleri seni sonunda bekliyor."] = "Kobolds pour out of Jasperlode Mine, gnolls cross the river and the Defias Brotherhood marches on the farms. Their leader waits for you at the end.",
    ["Grrr... taze et!"] = "Grrr... fresh meat!",
    ["Mother Fang madenden fırlıyor!"] = "Mother Fang skitters out of the mine!",
    ["VanCleef kafalarınız için çok para öder!"] = "VanCleef pay big for your heads!",
    ["Saldırı altındayız! Hey, tayfalar! Saldırganları püskürtün!"] = "We're under attack! Avast, ye swabs! Repel the invaders!",
    ["Kimse Kardeşliğe meydan okuyamaz!"] = "None may challenge the Brotherhood!",
    ["Nightbane'in Gecesi"] = "Night of the Nightbane",
    ["Raven Hill'in mezarları açık duruyor. Worgen'ler ağaçların arasında avlanıyor ve Morbent Fel, Duskwood'un ölülerini savaşa çağırıyor."] = "The graves of Raven Hill stand open. Worgen hunt between the trees, and Morbent Fel calls the dead of Duskwood to war.",
    ["Naraxis dallardan düşüyor!"] = "Naraxis drops from the branches!",
    ["Ölümde orduma katılacaksın!"] = "You will join my army in death!",
    ["Stitches aç! Stitches yer!"] = "Stitches hungry! Stitches eat!",
    ["Lupos uluyor ve Nightbane karşılık veriyor!"] = "Lupos howls, and the Nightbane answer!",
    ["Raven Hill'in ölüleri emrimle kalkıyor!"] = "The dead of Raven Hill rise at my command!",
    ["Yanan Lejyon"] = "The Burning Legion",
    ["Vadinin üzerinde bir iblis kapısı yırtılıyor. İmp'ler, iblis köpekleri ve satirler akın ediyor, ardından Lord Kazzak geliyor."] = "A demon gate tears open over the gulch. Imps, felhounds and satyrs pour through, and Lord Kazzak follows.",
    ["Dünyanız yakmamız için bizim!"] = "Your world is ours to burn!",
    ["Lejyon'un önünde diz çök!"] = "Kneel before the Legion!",
    ["Dehşet lordları Warsong'u hatırlıyor. Ya sen?"] = "The dreadlords remember Warsong. Do you?",
    ["Hel'nurath'ı çağırmaya kim cüret eder? Ruhun artık benim!"] = "Who dares summon Hel'nurath? Your soul is forfeit!",
    ["Tüm ölümlüler yok olacak!"] = "All mortals will perish!",
    ["Yaylalar Ayaklanıyor"] = "The Highlands Rise",
    ["Havzanın sancakları yere indiğinde yaylalar onu almaya geliyor: tepelerden inen Boulderfist ogreları ve Witherbark trolleri, arkalarında da Alterac'ın son lordunun havzayı kendine almak için gönderdiği Syndicate."] = "With the Basin's banners down, the Highlands come for it: Boulderfist ogres and Witherbark trolls out of the hills, and the Syndicate behind them, sent by the last lord of Alterac to take it for his own.",
    ["Dire Maul'un Kapıları"] = "The Gates of Dire Maul",
    ["Gordunni ogreleri, arkalarında Woodpaw gnoll'ları ve Feralas'ın vahşi yaratıklarıyla Dire Maul'dan çıkıyor. Ormanı almaya bizzat Kral Gordok geliyor."] = "The Gordunni ogres break out of Dire Maul with the Woodpaw gnolls and the wild things of Feralas behind them. King Gordok himself comes to claim the forest.",
    ["Kanın ormanın yozlaşmasını besleyecek!"] = "Your blood will feed the forest's corruption!",
    ["Vahşi doğa seni yutacak!"] = "The wilds will consume you!",
    ["Warpwood'u kim rahatsız ediyor?"] = "Who disturbs the Warpwood?",
    ["Immol'thar hapishanesinden kurtuluyor!"] = "Immol'thar breaks free of its prison!",
    ["Ben ezmek! Sen ölmek!"] = "Me smash! You die!",
    ["Kan Tanrısı Uyanıyor"] = "The Blood God Wakes",
    ["Hakkari'ler Arena'yı bir sunağa çeviriyor. Troller, raptorlar ve Kan Tanrısı'nın yılanları arenayı dolduruyor ve Hakkar the Soulflayer yeniden dünyada yürüyor."] = "The Hakkari turn the Arena into an altar. Trolls, raptors and the Blood God's serpents fill the ring, and Hakkar the Soulflayer walks the world again.",
    ["Lord Hir'eek, bana intikam kanatları ver!"] = "Lord Hir'eek, grant me wings of vengeance!",
    ["Nefretin halkaları açılsın!"] = "Let the coils of hate unfurl!",
    ["Ruhlarınızı bizzat Hakkar'a yedireceğim!"] = "I'll feed your souls to Hakkar himself!",
    ["Büyük gösteriye hoş geldiniz dostlar. Buyrun, gelin ve ölün!"] = "Welcome to da great show, friends. Step right up to die!",
    ["KİBİR DÜNYANIZIN SONUNU MÜJDELER. GELİN, ÖLÜMLÜLER! SOULFLAYER'IN GAZABIYLA YÜZLEŞİN!"] = "PRIDE HERALDS THE END OF YOUR WORLD. COME, MORTALS! FACE THE WRATH OF THE SOULFLAYER!",
    ["Donmuş Topraklar"] = "The Frozen Wilds",
    ["Vadi uyanıyor. Trogg'lar madenlerden akın ediyor, kurtlar açlıktan kıvranıyor ve Buz Lordu karın altında kıpırdanıyor."] = "The valley wakes. Troggs swarm from the mines, the wolves are starving, and the Ice Lord stirs beneath the snow.",
    ["Korrak cılızları ezmek!"] = "Korrak smash puny ones!",
    ["Ormanın uykusunu kim bölüyor?"] = "Who disturbs the slumber of the forest?",
    ["Ben Buz Lordu'yum. Kanın damarlarında donacak!"] = "I am the Ice Lord. Your blood will freeze in your veins!",
    ["Dağ hatırlıyor. Dağ seni gömecek!"] = "The mountain remembers. The mountain will bury you!",
    ["Burası benim korumam altında. Arkanın gizemleri dokunulmaz kalacak!"] = "This place is under my protection. The mysteries of the arcane shall remain inviolate!",
    ["Blackrock'un Lordu"] = "The Lord of Blackrock",
    ["Dark Iron'lar ve Blackrock klanı, yanlarında ateş elementalleri ve ejderha soyuyla birlikte dağdan çıkıyor. Üzerlerinde Blackrock'un Lordu daireler çiziyor."] = "The Dark Iron and the Blackrock clan march out of the mountain together, fire elementals and dragonkin at their side. Above them circles the Lord of Blackrock.",
    ["Dark Iron! Silah başına! Davetsiz misafirleri ezin!"] = "Dark Iron! To arms! Crush the intruders!",
    ["Blackrock asla düşmeyecek! Gerçek Ordu için!"] = "Blackrock will never fall! For the true Horde!",
    ["Tahtın yardımına gelin!"] = "Come to aid the Throne!",
    ["Pervasız ölümlüler! Kimse yaşayan alevin oğullarına meydan okuyamaz!"] = "Reckless mortals! None may challenge the sons of the living flame!",
    ["Aferin uşaklarım. Ölümlülerin cesareti azalmaya başladı! Şimdi Blackrock Spire'ın gerçek Lordu'yla nasıl başa çıkacaklarını görelim!"] = "Well done, my minions. The mortals' courage begins to wane! Now let's see how they contend with the true Lord of Blackrock Spire!",
    ["Kadim Tanrı Kıpırdanıyor"] = "The Old God Stirs",
    ["Scarab Wall yıkıldı. Silithid sürüsü ve Qiraji lejyonları kumlara yayılıyor ve arkalarında C'Thun gözünü açıyor."] = "The Scarab Wall has fallen. The silithid swarm and the Qiraji legions spill across the sands, and behind them C'Thun opens its eye.",
    ["Kurinnaxx yüzeye çıkarken kumlar patlıyor!"] = "The sands erupt as Kurinnaxx surfaces!",
    ["Küstah aptal! Seni kendim öldüreceğim!"] = "Impudent fool! I will kill you myself!",
    ["Prenses Huhuran çılgına dönüyor!"] = "Princess Huhuran goes into a frenzy!",
    ["Çölün kumları, yükselin ve güneşi örtün!"] = "Sands of the desert, rise and block out the sun!",
    ["ZATEN ÖLÜSÜN."] = "YOU ARE ALREADY DEAD.",
    ["Deneyim"] = "Experience",
    ["Savaş Alanı Sandığı"] = "Battleground Cache",
    ["Hız Rünü"] = "Speed Rune",
    ["Çılgınlık Rünü"] = "Berserker Rune",
    ["Yenilenme Rünü"] = "Restoration Rune",
    ["Mıknatıs"] = "Magnet",
    ["Savaş Alanının Kenarı"] = "Edge of the Battlefield",
    ["Nesne"] = "Object",
    ["Baş"] = "Head",
    ["Omuz"] = "Shoulder",
    ["Göğüs"] = "Chest",
    ["Bel"] = "Waist",
    ["Bacaklar"] = "Legs",
    ["Ayaklar"] = "Feet",
    ["Bilek"] = "Wrist",
    ["Eller"] = "Hands",
    ["Ana El"] = "Main Hand",
    ["Yan El"] = "Off Hand",
    ["Menzilli"] = "Ranged",
    ["Plaka"] = "Plate",
    ["İki Elli Kılıç"] = "Two-Hand Sword",
    ["İki Elli Gürz"] = "Two-Hand Mace",
    ["Zincir"] = "Mail",
    ["Deri"] = "Leather",
    ["Hançer"] = "Dagger",
    ["Kılıç"] = "Sword",
    ["Kumaş"] = "Cloth",
    ["Asa"] = "Staff",
    ["Gürz"] = "Mace",
    ["Kalkan"] = "Shield",
    ["Balta"] = "Axe",
    ["Yan Elde Tutulan"] = "Held In Off-hand",
    ["Tüfek"] = "Gun",
    ["Fırlatılan"] = "Thrown",
    ["İki Elli Balta"] = "Two-Hand Axe",
    ["Sade bir iş, ama darbenin canı acıtan yere inmesine yardım eder."] = "Plain work, but it helps a blow land where it hurts.",
    ["Sağlam, görünüşü pek bir şey olmasa da."] = "Sturdy, if nothing much to look at.",
    ["İyi oturuyor; giyeni dinç ve hazır tutar."] = "Well fitted; it keeps its wearer fresh and ready.",
    ["Hafif ve iyi kesilmiş; seni asla yavaşlatmaz."] = "Light and well cut; it never slows you down.",
    ["Sade, rahat ve içinde dinlenmesi kolay."] = "Simple, comfortable, and easy to rest in.",
    ["Kalın ve sıcak, yolda geçen uzun günler için yapılmış."] = "Thick and warm, made for long days on the road.",
    ["Hızlı hareket edip sert vurmak için biçilmiş."] = "Cut for moving quickly and hitting hard.",
    ["Yapanın gözü keskindi, giyeninki de öyle olacak."] = "Its maker had a good eye, and so will its wearer.",
    ["Yüz öldürücü darbeyle çentiklenmiş."] = "Notched by a hundred killing blows.",
    ["Bir baltayı savuşturacak kadar kalın dövülmüş."] = "Hammered thick enough to turn an axe.",
    ["Hücumdan asla yorulmayanların giydiği."] = "Worn by those who never tire of the charge.",
    ["Düşmana ilk ulaşacak ve zırhındaki boşluğu bulacak kadar hafif."] = "Light enough to reach the foe first, and find the gap in its armor.",
    ["Bir gazinin teçhizatı: yaralar kapanır ve sonraki darbe hazırdır."] = "A veteran's gear: the wounds close, and the next blow is ready.",
    ["Kanayıp ayakta kalanlar için yapılmış."] = "Made for those who bleed and keep standing.",
    ["Kaçanı yakalamak için yapılmış."] = "Made for running down what flees.",
    ["Kılıcın her savruluşu daha uzağa erişir."] = "Every sweep of the blade carries further.",
    ["Kötüleri cezalandırmak için kutsanmış."] = "Blessed for the smiting of the wicked.",
    ["Kutsanmış çelik: Işık darbeyi saptırır."] = "Consecrated steel: the Light turns the blow aside.",
    ["Işık, taşıyanın dualarına çabucak karşılık verir."] = "The Light answers its bearer's prayers swiftly.",
    ["Adaletin eli çabuk ve kesindir."] = "Swift is the hand of justice, and sure.",
    ["İnanç, hükümler arasında taşıyanını iyileştirir."] = "Faith mends its bearer between judgements.",
    ["Işık, taşıyanını ölümlü sınırların ötesinde ayakta tutar."] = "The Light keeps its bearer standing past mortal limits.",
    ["Scourge'u ezip geçen haçlı için."] = "For the crusader who rides down the Scourge.",
    ["Kutsal ışıltısı geniş yayılır ve isabetle yakar."] = "Its holy radiance spreads wide and burns true.",
    ["Her atış kalbi bulur."] = "Every shot finds the heart.",
    ["Ölmeyi reddeden bir canavardan kesilmiş."] = "Cut from a beast that would not die.",
    ["Keskin gözlü ve yorulmaz, yeniden atmaya her an hazır."] = "Keen-eyed and tireless, ever ready to loose again.",
    ["İzde hafif, atışta isabetli."] = "Light on the trail, sure on the shot.",
    ["Sabırlı avcı dinlenir ve sonraki tuzağı hazırlar."] = "The patient hunter rests, and readies the next trap.",
    ["Vahşi doğada geçen uzun mevsimler için yapılmış."] = "Made for long seasons in the wild.",
    ["Sürüyle koşar, sürüyle ısırır."] = "Runs with the pack, and bites with it.",
    ["Yukarıdan hiçbir şey erişiminden kaçamaz."] = "From high above, nothing escapes its reach.",
    ["İşi bitiren darbe için yapılmış."] = "Made for the strike that ends it.",
    ["Gölgelerin altında perçinli, ters giden kavga için."] = "Studded beneath the shadows, for the fight that goes wrong.",
    ["Giyeni asla hazırda bir numarası olmadan yakalanmaz."] = "Its wearer is never caught without a trick ready.",
    ["Hızlı ayaklar ve sırtta daha da hızlı bir bıçak."] = "Quick feet, and a quicker blade in the back.",
    ["Gölgelerde soluklan; sonraki numara hazır."] = "Catch your breath in the shadows; the next trick is ready.",
    ["Her pusudan sağ çıkan için."] = "For the one who walks out of every ambush.",
    ["Dal, kes, kaybol."] = "Dart in, cut, gone.",
    ["Bıçakları geniş bir yelpazeyle açılır ve hayati noktaları bulur."] = "Its knives fan wide and find the vitals.",
    ["Kutsal gazap da gölge de isabetle vurur."] = "Holy wrath and shadow alike strike true.",
    ["Zarara karşı korumalarla dokunmuş."] = "Woven with wards against harm.",
    ["Giyenin duaları çabucak kabul olur."] = "Its wearer's prayers are answered swiftly.",
    ["Adımı hafif, sözü kesin."] = "Light of step and certain of word.",
    ["Her ipliğine meditasyon işlenmiş."] = "Meditation woven into every thread.",
    ["Giyenini her sınavda ayakta tutmak için kutsanmış."] = "Blessed to sustain its wearer through any trial.",
    ["Bağnazın giysisi, kargaşanın içine yürümek için yapılmış."] = "The zealot's garb, made to walk into the fray.",
    ["Kutsamaları uzağa erişir ve isabetle iner."] = "Its blessings reach far and fall true.",
    ["Fırtınanın öfkesi, rünlerine bağlanmış."] = "The fury of the storm, bound in its runes.",
    ["Toprağın ruhları tarafından kutsanmış."] = "Blessed by the spirits of the earth.",
    ["Elementler giyenine gecikmeden karşılık verir."] = "The elements answer its wearer without delay.",
    ["Rüzgâr giyenini taşır ve darbesine yön verir."] = "The wind carries its wearer, and guides the strike.",
    ["Suyun sabrı: iyileştirir ve geri döner."] = "Water's patience: it heals, and it returns.",
    ["Gelgitler giyenini tekrar tekrar yeniler."] = "The tides restore its wearer, again and again.",
    ["Ruh kurdu giyeninin yanında koşar."] = "The spirit wolf runs at its wearer's side.",
    ["Şimşeği uzağa sıçrar ve isabetle vurur."] = "Its lightning leaps far and strikes true.",
    ["Arkan rünler her büyüyü keskinleştirir."] = "Arcane runes sharpen every spell.",
    ["İplikleri bir ayaz koruması taşır."] = "Its threads hold a ward of frost.",
    ["Dokusu sonraki büyüyü hızlandırır."] = "Its weave hastens the next spell.",
    ["Havadan hafif, bir göz kırpması kadar kesin."] = "Lighter than air, and precise as a blink.",
    ["Arkan güç, büyüler arasında giyenini iyileştirir."] = "The arcane mends its wearer between spells.",
    ["Daha zayıf büyücüleri yere serecek şeye dayanmak için büyülenmiş."] = "Enchanted to endure what would fell lesser magi.",
    ["Hareket halinde, sert atılan büyüler."] = "Spells loosed on the move, and loosed hard.",
    ["Kar fırtınaları daha geniş düşer, daha derin ısırır."] = "Its blizzards fall wider and bite deeper.",
    ["Dikişlerindeki fel rünleri öldürmeye aç."] = "Fel runes along its seams hunger for the kill.",
    ["Bir iblis derisiyle ciltlenmiş."] = "Bound with a demon's hide.",
    ["Antlaşma hayat verir ve daha çabuk dönen büyüler."] = "The pact grants life, and spells that return sooner.",
    ["Gölge giyenini hızlandırır ve laneti hedefine ulaştırır."] = "Shadow hastens its wearer and guides the curse home.",
    ["Ölenlerden emilen hayat giyenini iyileştirir."] = "Life siphoned from the dying mends its wearer.",
    ["Giyenin hayatı bağlı bir ruhla demirlenmiş."] = "Its wearer's life is anchored by a bound soul.",
    ["Felhunter derisi, kovalamaca için yapılmış."] = "Felhunter leather, made for the chase.",
    ["Gölge alevi uzağa yayılır ve derin yakar."] = "Its shadowflame spreads far and burns deep.",
    ["Büyük kedinin pençeleri kadar keskin."] = "Sharp as the great cat's claws.",
    ["Büyük ayının postu kadar kalın."] = "Thick as the hide of the great bear.",
    ["Doğanın armağanları giyenine çabucak döner."] = "Nature's gifts return swiftly to its wearer.",
    ["Geyik kadar hızlı, pençe kadar kesin."] = "Swift as the stag, sure as the claw.",
    ["Moonkin kadar bilge; doğa büyüler arasında iyileştirir."] = "Wise as the moonkin; nature mends between spells.",
    ["Zümrüt Rüya giyenini ayakta tutar."] = "The Emerald Dream sustains its wearer.",
    ["Sürünün temposunda, av için yapılmış."] = "Made for the hunt, at the pace of the pack.",
    ["Doğanın gazabı uzağa erişir ve isabetle vurur."] = "Nature's wrath reaches far and strikes true.",
    ["Zirve. Her oyuna Mortal Strike ile başlarsın; Mortal Strike veya Execute ile yapılan öldürücü darbe onu hemen yeniden hazırlar, saniyede en fazla bir kez."] = "Capstone. You start every run with Mortal Strike; a killing blow by Mortal Strike or Execute readies it again at once, at most once a second.",
    ["Dönüm noktası. Whirlwind ve Bloodthirst iki kez vurur: vurdukları her şey hemen darbenin %40'ı kadar yeniden vurulur."] = "Milestone. Whirlwind and Bloodthirst strike twice: everything they hit is struck again at once for 40% of the blow.",
    ["Zirve. Her oyuna Whirlwind ile başlarsın ve dönmeyi hiç bırakmazsın: her 3 sn'de bedava bir Whirlwind."] = "Capstone. You start every run with Whirlwind, and you never stop spinning: a free Whirlwind every 3 sec.",
    ["Seni öldürecek bir darbe bunun yerine seni %40 canla bırakır, sonra bedava bir Shield Slam ve azami canının %10'u kadar bir kalkanla karşılık verirsin. 90 sn'de bir kez."] = "A blow that would kill you leaves you at 40% health instead, then you answer with a free Shield Slam and a shield of 10% of your maximum health. Once every 90 sec.",
    ["Zirve. Her oyuna Shield Slam ile başlarsın, hasar azaltman %60 yerine %70'e ulaşabilir, kullandığın her büyü ek olarak azami canının %1.5'i kadar hasar verir ve Shield Slam ayrıca hedefinin azami canının %2'si kadar vurur."] = "Capstone. You start every run with Shield Slam, your damage reduction can reach 70% instead of 60%, and every spell you cast deals an extra 1.5% of your maximum health, and Shield Slam also strikes for 2% of its target's maximum health.",
    ["Kutsal"] = "Holy",
    ["Dönüm noktası. Holy Shock'un kritik vuruşları etrafına bedava bir Holy Wrath indirir, en fazla 3 sn'de bir."] = "Milestone. Holy Shock's critical strikes call down a free Holy Wrath around you, at most once every 3 sec.",
    ["Zirve. Her 14 sn'de senden kendiliğinden bir Holy Wrath patlar."] = "Capstone. A Holy Wrath bursts from you on its own every 14 sec.",
    ["Dönüm noktası. İsabet eden her Hammer of Justice altındaki toprağı kutsar: bedava bir Consecration, en fazla 4 sn'de bir."] = "Milestone. Every Hammer of Justice that lands hallows the ground beneath you: a free Consecration, at most once every 4 sec.",
    ["Seni öldürecek bir darbe bunun yerine seni %30 canla bırakır; bedava bir Divine Shield ve bedava bir Consecration ile sarılırsın. 90 sn'de bir kez."] = "A blow that would kill you leaves you at 30% health instead, wrapped in a free Divine Shield and a free Consecration. Once every 90 sec.",
    ["Zirve. Azami canın %15 daha yüksek, kullandığın her büyü ek olarak azami canının %1'i kadar hasar verir, Hammer of Justice ayrıca hedefinin azami canının %1.5'i kadar vurur ve kırılan bir kalkan kutsal ışıkla patlar: emdiğinin yarısı, en çok tuttuğunun yarısına kadar, 10 m içindeki her düşmana vurur."] = "Capstone. Your maximum health is 15% higher, every spell you cast deals an extra 1% of your maximum health, Hammer of Justice also strikes for 1.5% of its target's maximum health, and a shield that breaks bursts in holy light: half of what it absorbed, up to half the most it held, strikes every enemy within 10 yd.",
    ["Dönüm noktası. Yanında bir kurt savaşır, vurduğun şeyleri ısırır."] = "Milestone. A wolf fights at your side, biting what you shoot.",
    ["Zirve. Her oyuna Frost Trap ile başlarsın ve her 5 sn'de ayaklarının dibine kendiliğinden bir Explosive Trap kurulur."] = "Capstone. You start every run with Frost Trap, and an Explosive Trap sets itself at your feet every 5 sec.",
    ["Dönüm noktası. Sinister Strike ve Backstab iki bıçakla vurur: vurdukları her şey hemen darbenin %50'si kadar yeniden vurulur."] = "Milestone. Sinister Strike and Backstab strike with both blades: everything they hit is struck again at once for 50% of the blow.",
    ["Dönüm noktası. Seni öldürecek bir darbe bunun yerine seni %25 canla bırakır ve gölgelere karışırsın: 3 sn boyunca hiçbir şey sana dokunamaz. 2.5 dk'da bir kez."] = "Milestone. A blow that would kill you leaves you at 25% health instead, and you fade into the shadows: nothing can touch you for 3 sec. Once every 2.5 min.",
    ["Dönüm noktası. Her 6 sn'de bedava bir Gouge etrafındaki düşmanları sersemletir."] = "Milestone. A free Gouge stuns the enemies around you every 6 sec.",
    ["Dönüm noktası. Kırılan bir Power Word: Shield hemen yeniden kurulur, en fazla 15 sn'de bir."] = "Milestone. A broken Power Word: Shield is raised again at once, at most once every 15 sec.",
    ["Zirve. Kendi başına saldırırsın: yaklaşık her 3 sn'de bedava bir Penance, en yakın düşmanlara üç kutsal ışık oku."] = "Capstone. You strike out on your own: a free Penance about every 3 sec, three bolts of holy light at the nearest enemies.",
    ["Dönüm noktası. Her 24 sn'de senden kendiliğinden bir Holy Nova patlar."] = "Milestone. A Holy Nova bursts from you on its own every 24 sec.",
    ["Zirve. Smite 1 düşmana daha vurur ve her Smite kritik vuruşu bedava bir Holy Nova tetikler."] = "Capstone. Smite strikes 1 more enemy, and every Smite critical strike sets off a free Holy Nova.",
    ["Gölge"] = "Shadow",
    ["Dönüm noktası. Chain Lightning 3 düşmana daha sıçrar ve her sıçrayışta hiçbir şey kaybetmez."] = "Milestone. Chain Lightning jumps to 3 more enemies and loses nothing with each jump.",
    ["Zirve. Her oyuna Chain Lightning ile başlarsın ve her 3 sn'de ikinci bir Chain Lightning kendiliğinden kullanılır."] = "Capstone. You start every run with Chain Lightning, and a second Chain Lightning casts itself every 3 sec.",
    ["Dönüm noktası. Her oyuna Searing Totem ile başlarsın ve diktiğin her totem yanına ikincisini diker."] = "Milestone. You start every run with Searing Totem, and every totem you set down sets a second one beside it.",
    ["Dönüm noktası. Seni öldürecek bir darbe bunun yerine seni %50 canla bırakır, 2 dk'da bir kez."] = "Milestone. A blow that would kill you leaves you at 50% health instead, once every 2 min.",
    ["Zirve. Her oyuna Magma Totem ile başlarsın ve her 14 sn'de ikinci bir Searing Totem kendiliğinden dikilir."] = "Capstone. You start every run with Magma Totem, and a second Searing Totem drops on its own every 14 sec.",
    ["Arkan"] = "Arcane",
    ["Ateş"] = "Fire",
    ["Dönüm noktası. Her dördüncü Ateş kritik vuruşu bedava bir Pyroblast kullanır, saniyede en fazla iki kez."] = "Milestone. Every fourth Fire critical strike casts a free Pyroblast, at most twice a second.",
    ["Buz"] = "Frost",
    ["Zirve. Her oyuna Fireball yerine Frostbolt ile başlarsın. Yanında Frostbolt fırlatan bir Su Elementali savaşır ve her 8 sn'de senden bedava bir Frost Nova patlar."] = "Capstone. You start every run with Frostbolt instead of Fireball. A Water Elemental fights at your side, hurling Frostbolts, and a free Frost Nova bursts from you every 8 sec.",
    ["Dönüm noktası. Üzerinde Corruption veya Curse of Agony varken ölen bir düşmanın her etkisi ona en yakın düşmana sıçrar."] = "Milestone. When an enemy dies with Corruption or Curse of Agony on it, each jumps to the enemy nearest it.",
    ["Zamanla hasar veren etkilerinin her tiki seni hasarının %1'i kadar iyileştirir."] = "Every tick of your damage-over-time effects heals you for 1% of it.",
    ["Dönüm noktası. Yanında ateş okları fırlatan bir İmp savaşır."] = "Milestone. An Imp fights at your side, hurling bolts of fire.",
    ["Zirve. Her 13 sn'de kendiliğinden ikinci bir Rain of Fire yağar ve yanan zemini dokunduğunu yavaşlatır."] = "Capstone. A second Rain of Fire falls on its own every 13 sec, and its burning ground slows what it touches.",
    ["Dönüm noktası. Etrafına yıldızlar düşer: her 4 sn'de bedava bir Starfire."] = "Milestone. Stars fall around you: a free Starfire every 4 sec.",
    ["Zirve. Yanında iki treant savaşır ve her oyuna Moonfire ile başlarsın."] = "Capstone. Two treants fight at your side, and you start every run with Moonfire.",
    ["Zirve. Dire Bear Form'da savaşırsın: azami canın %25 artar, aldığın hasar %10 azalır. Her 3 sn'de etrafında bedava bir Swipe savrulur ve Swipe'ın vurduğu her düşman seni azami canının %0.3'i kadar iyileştirir. Her oyuna Wrath yerine Shred ile başlarsın. Cat Form'u da öğrenemezsin."] = "Capstone. You fight in Dire Bear Form: 25% more maximum health and 10% less damage taken. A free Swipe tears around you every 3 sec, and every enemy Swipe hits heals you for 0.3% of your maximum health. You start every run with Shred instead of Wrath. You can't also learn Cat Form.",
    ["Zirve. Cat Form'da savaşırsın: %10 daha fazla hasar, %10 daha fazla kritik vuruş şansı ve %15 daha hızlı hareket; Shred'in bekleme süresi %20 daha kısadır. Her oyuna Wrath yerine Shred ile başlarsın. Dire Bear Form'u da öğrenemezsin."] = "Capstone. You fight in Cat Form: 10% more damage, 10% more critical strike chance and 15% faster movement, and Shred's cooldown is 20% shorter. You start every run with Shred instead of Wrath. You can't also learn Dire Bear Form.",
    ["Dönüm noktası. Canın %40'ın altına düşünce üzerinde bedava bir Regrowth açar, 8 sn'de bir kez."] = "Milestone. Falling below 40% health makes a free Regrowth bloom on you, once every 8 sec.",
    ["Zirve. Azami canını aşan iyileştirme, onun %20'sine kadar bir kalkana dönüşür ve her 6 sn'de üzerinde bedava bir Rejuvenation açar."] = "Capstone. Healing beyond your maximum health becomes a shield, up to 20% of it, and a free Rejuvenation blooms on you every 6 sec.",
    ["Kurt"] = "Wolf",
    ["İmp"] = "Imp",
    ["Ruh Kurdu"] = "Spirit Wolf",
    ["Su Elementali"] = "Water Elemental",
    ["Zafer"] = "Victory",
    ["Bölge bonusu"] = "Zone bonus",
    ["İkinci Düşünce"] = "Second Thoughts",
    ["Her oyunda bir bedava yeniden çekme daha."] = "One more free reroll every run.",
    ["Her oyunda iki bedava yeniden çekme daha."] = "Two more free rerolls every run.",
    ["Her oyunda üç bedava yeniden çekme daha."] = "Three more free rerolls every run.",
    ["Sürgün"] = "Banish",
    ["Oyun başına bir kez bir kartı sürgün et: o oyunda bir daha çıkmaz ve el yeniden dağıtılır."] = "Once a run, banish a card: it never comes up again that run, and the hand is dealt again.",
    ["Oyun başına iki kez bir kartı sürgün et."] = "Twice a run, banish a card.",
    ["Oyun başına üç kez bir kartı sürgün et."] = "Three times a run, banish a card.",
    ["Geç"] = "Skip",
    ["Herhangi bir eli geç ve yerine biraz altın al."] = "Pass on any hand and take some gold instead.",
    ["Açılış Eli"] = "Opening Hand",
    ["Her oyundaki ilk seviye atlaman dört kart dağıtır."] = "Your first level-up of every run deals four cards.",
    ["Gazinin Dersleri"] = "Veteran's Lessons",
    ["Yetenek deneyimi en iyinden az olan bir sınıf %20 daha fazla kazanır."] = "A class with less talent experience than your best earns 20% more.",
    ["Yetenek deneyimi en iyinden az olan bir sınıf %40 daha fazla kazanır."] = "A class with less talent experience than your best earns 40% more.",
    ["Keskin Göz"] = "Keen Eye",
    ["Boss'ların her parçayı düşürme ihtimali %5 daha yüksek."] = "Bosses are 5% more likely to drop each piece.",
    ["Boss'ların her parçayı düşürme ihtimali %10 daha yüksek."] = "Bosses are 10% more likely to drop each piece.",
    ["Yoldaş"] = "Companion",
    ["Bir yoldaş her oyunda seni takip eder ve toplama menzilinin 25 m ötesine kadar sikkeleri ve deneyim pırıltılarını getirir, her 2 sn'de bir. Asla mıknatıs ya da sandık getirmez."] = "A companion follows you through every run and fetches coins and experience wisps up to 25 yd beyond your pickup radius, one every 2 sec. Never a magnet or a cache.",
    ["Uzun Tasma"] = "Long Leash",
    ["Yoldaşların toplama menzilinin 35 m ötesine kadar getirir."] = "Your companions fetch up to 35 yd beyond your pickup radius.",
