    { "^Rütbe (.-)/(.-)$", { "rank", "ranks" }, "Rank {rank}/{ranks}" },
    { "^(.-): %+(.-) güç$", { "who", "v" }, "{who}: +{v} strength" },
    { "^Rütbe (.-)$", { "n" }, "Rank {n}" },
    { "^Yeni: (.-)$", { "spell" }, "New: {spell}" },
    { "^%+(.-) şans$", { "p" }, "+{p} luck" },
    { "^RÜTBE (.-)$", { "n" }, "RANK {n}" },
    { "^(.-) muska$", { "rarity" }, "{rarity} amulet" },
    { "^%+(.-) Can$", { "n" }, "+{n} Health" },
    { "^(.-) puan$", { "n" }, "{n} points" },
    { "^(.-) kez$", { "n" }, "{n} times" },
    { "^(.-) / (.-)$", { "n", "total" }, "{n} of {total}" },
  },
}
